for (let i = 0; i < n; i++) f[i] = input[idx++];

const g = Array.from({ length: n }, () => []);
const gr = Array.from({ length: n }, () => []);
for (let i = 0; i < m; i++) {
    const a = input[idx++] - 1;
    const b = input[idx++] - 1;
    g[a].push(b);
    gr[b].push(a);
}

// Kosaraju to find SCCs
const used = new Array(n).fill(false);
const order = [];
function dfs1(v) {
    used[v] = true;
    for (const to of g[v]) if (!used[to]) dfs1(to);
    order.push(v);
}
for (let i = 0; i < n; i++) if (!used[i]) dfs1(i);

const comp = new Array(n).fill(-1);
let compCnt = 0;
function dfs2(v, c) {
    comp[v] = c;
    for (const to of gr[v]) if (comp[to] === -1) dfs2(to, c);
}
for (let i = n - 1; i >= 0; i--) {
    const v = order[i];
    if (comp[v] === -1) {
        dfs2(v, compCnt++);
        compCnt++;
    }
}

// Build condensation DAG
const dag = Array.from({ length: compCnt }, () => []);
const dagR = Array.from({ length: compCnt }, () => []);
const hasAssign = new Array(compCnt).fill(false);
const hasUse = new Array(compCnt).fill(false);

for (let v = 0; v < n; v++) {
    const c = comp[v];
    if (f[v] === 1) hasAssign[c] = true;
    if (f[v] === 2) hasUse[c] = true;
    for (const to of g[v]) {
        const ct = comp[to];
        if (c !== ct) {
            dag[c].push(ct);
            dagR[ct].push(c);
        }
    }
}

// Remove duplicate edges in DAG (optional but safer for DP)
for (let i = 0; i < compCnt; i++) {
    if (dag[i].length > 1) {
        const set = new Set(dag[i]);
        dag[i] = Array.from(set);
    }
    if (dagR[i].length > 1) {
        const set = new Set(dagR[i]);
        dagR[i] = Array.from(set);
    }
}

// Topological order of condensation DAG
const indeg = new Array(compCnt).fill(0);
for (let v = 0; v < compCnt; v++) {
    for (const to of dag[v]) indeg[to]++;
}
const q = [];
for (let i = 0; i < compCnt; i++) if (indeg[i] === 0) q.push(i);
const topo = [];
for (let qi = 0; qi < q.length; qi++) {
    const v = q[qi];
    topo.push(v);
    for (const to of dag[v]) {
        indeg[to]--;
        if (indeg[to] === 0) q.push(to);
