    if (f[v] === 2) hasUse[comp[v]] = true;
}

const cg = Array.from({ length: compCnt }, () => []);
const cgr = Array.from({ length: compCnt }, () => []);
const edgeSet = new Set();
for (let v = 0; v < n; v++) {
    const cv = comp[v];
    for (const to of g[v]) {
        const cu = comp[to];
        if (cv !== cu) {
            const key = cv * compCnt + cu;
            if (!edgeSet.has(key)) {
                edgeSet.add(key);
                cg[cv].push(cu);
                cgr[cu].push(cv);
            }
        }
    }
}

// DP forward: can reach a use from component
const canReachUse = new Array(compCnt).fill(false);
const indeg = new Array(compCnt).fill(0);
