    for (const to of cg[v]) indeg[to]++;
}

let queue = [];
for (let i = 0; i < compCnt; i++) if (indeg[i] === 0) queue.push(i);

let topo = [];
while (queue.length) {
    const v = queue.shift();
    topo.push(v);
    for (const to of cg[v]) {
        indeg[to]--;
        if (indeg[to] === 0) queue.push(to);
    }
}

for (let i = compCnt - 1; i >= 0; i--) {
    const v = topo[i];
    if (hasUse[v]) canReachUse[v] = true;
    for (const to of cg[v]) {
        if (canReachUse[to]) canReachUse[v] = true;
    }
}

// DP backward: can be reached from an assign without passing another assign
const canFromAssign = new Array(compCnt).fill(false);
const outdeg = new Array(compCnt).fill(0);
